crossfade_specification.hise_implementation_script:
// HISE ScriptProcessor Live Crossfader Formulation:
inline function getRaisedCosineGainOut(normalizedTime) {
    return 0.5 * (1.0 + Math.cos(Math.PI * normalizedTime));
}
inline function getRaisedCosineGainIn(normalizedTime) {
    return 0.5 * (1.0 - Math.cos(Math.PI * normalizedTime));
}
